insert into homework_private.templates(lesson_id,definition) values ('a1-2-w4-l1','{"id":"a1-2-w4-l1","version":"20261004-flow-3","level":"A1.2","title":"Примерочная","steps":[{"role":"words","exercise":{"version":1,"id":"a12w4l1-words","kind":"matching","title":"Match the pictures with the words.","layout":"picture-word","items":[{"id":"picture-coat","text":"Picture 1","assetId":"A1M4L1_IMAGE_01","alt":"A coat","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/coat-cutout.webp","imageWidth":1122,"imageHeight":1402,"correctId":"coat"},{"id":"picture-sweater","text":"Picture 2","assetId":"A1M4L1_IMAGE_02","alt":"A sweater","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/sweater-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"sweater"},{"id":"picture-blouse","text":"Picture 3","assetId":"A1M4L1_IMAGE_03","alt":"A blouse","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/blouse-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"blouse"},{"id":"picture-skirt","text":"Picture 4","assetId":"A1M4L1_IMAGE_04","alt":"A skirt","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/skirt-cutout.webp","imageWidth":1122,"imageHeight":1402,"correctId":"skirt"},{"id":"picture-suit","text":"Picture 5","assetId":"A1M4L1_IMAGE_05","alt":"A suit","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/suit-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"suit"},{"id":"picture-hat","text":"Picture 6","assetId":"A1M4L1_IMAGE_06","alt":"A hat","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/hat-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"hat"}],"options":[{"id":"skirt","text":"skirt"},{"id":"hat","text":"hat"},{"id":"coat","text":"coat"},{"id":"suit","text":"suit"},{"id":"blouse","text":"blouse"},{"id":"sweater","text":"sweater"}]}},{"role":"listenRepeat","exercise":{"version":1,"id":"a12w4l1-listen-repeat","kind":"audio","title":"Listen and repeat.","layout":"listen-repeat","audioPending":true,"instruction":"Listen to the words and sentences. Repeat them out loud.","items":[{"id":"coat","text":"coat","audioId":"A1M4L1_WORD_01","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_WORD_01_r3.mp3","example":"I need a coat for work.","exampleAudioId":"A1M4L1_SENTENCE_01","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_SENTENCE_01_r2.mp3"},{"id":"sweater","text":"sweater","audioId":"A1M4L1_WORD_02","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_WORD_02.mp3","example":"My sweater is in the wardrobe.","exampleAudioId":"A1M4L1_SENTENCE_02","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_SENTENCE_02.mp3"},{"id":"blouse","text":"blouse","audioId":"A1M4L1_WORD_03","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_WORD_03_cut1.wav","example":"My sister wants this blouse.","exampleAudioId":"A1M4L1_SENTENCE_03","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_SENTENCE_03.mp3"},{"id":"skirt","text":"skirt","audioId":"A1M4L1_WORD_04","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_WORD_04.mp3","example":"I like this skirt.","exampleAudioId":"A1M4L1_SENTENCE_04","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_SENTENCE_04.mp3"},{"id":"suit","text":"suit","audioId":"A1M4L1_WORD_05","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_WORD_05.mp3","example":"My father has a suit for work.","exampleAudioId":"A1M4L1_SENTENCE_05","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_SENTENCE_05.mp3"},{"id":"hat","text":"hat","audioId":"A1M4L1_WORD_06","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_WORD_06_r2.mp3","example":"I like your hat.","exampleAudioId":"A1M4L1_SENTENCE_06","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l1/listen-repeat/A1M4L1_SENTENCE_06.mp3"}]}},{"role":"practice","exercise":{"version":1,"id":"a12w4l1-language-practice","kind":"gaps","title":"Choose the correct option.","inputMode":"select","items":[{"id":"sentence4","segments":["This blouse ",{"id":"look4","answers":["looks like"],"options":["looks like","looks"]}," my old blouse."]},{"id":"sentence2","segments":["These sweaters ",{"id":"look2","answers":["look like"],"options":["look","look like"]}," my sweaters at home."]},{"id":"sentence5","segments":["How does this suit ",{"id":"look5","answers":["look"],"options":["looks","look"]},"?"]},{"id":"sentence1","segments":["This coat ",{"id":"look1","answers":["looks"],"options":["looks","looks like"]}," expensive."]},{"id":"sentence3","segments":["This hat ",{"id":"look3","answers":["looks"],"options":["looks","look"]}," unusual."]}]}},{"role":"rule","exercise":{"version":1,"id":"a12w4l1-language-focus-homework-rule","kind":"rule-page","title":"Как описать внешний вид вещи","blocks":[{"type":"rule","title":"Как описать внешний вид вещи","text":"Когда вы хотите сказать, как выглядит вещь, используйте look / looks + прилагательное. Например, The sweater looks warm — «Свитер выглядит тёплым». Вы делитесь впечатлением по внешнему виду.\n\nЕсли вещь напоминает вам другую, используйте look / looks like + существительное или сочетание с ним: This coat looks like my old coat — «Это пальто похоже на моё старое пальто». Здесь like означает сходство, а не «нравится».\n\nСравните:\nIt looks good. — Мы описываем впечатление.\nIt looks like my coat. — Мы говорим, на что вещь похожа.\n\nФорма глагола зависит от того, о ком или о чём вы говорите:\nI / you / we / they → look\nhe / she / it → looks\n\nПоэтому об одном предмете говорим The coat looks good, а о нескольких — The coats look good.\n\nПосле like действуют знакомые правила артиклей: like a coat, like an old coat, но like my coat — перед my артикль не нужен.\n\nЧтобы спросить о внешнем впечатлении, используйте How does it look? — «Как это выглядит?» После does глагол look стоит без окончания -s.","highlights":["look / looks + прилагательное","The sweater looks warm","look / looks like + существительное или сочетание с ним","This coat looks like my old coat","like","It looks good.","It looks like my coat.","I / you / we / they → look","he / she / it → looks","The coat looks good","The coats look good","like a coat","like an old coat","like my coat","my","How does it look?","does","look","-s"]}]}},{"role":"translation","exercise":{"version":1,"id":"L1-homework-1","kind":"writing","title":"Translate into English.","instruction":"Переведите на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Как смотрится это пальто?","acceptedAnswers":["How does this coat look?","How does this coat look"],"normalization":"translation"},{"id":"2","prompt":"Оно выглядит дорогим.","acceptedAnswers":["It looks expensive.","It looks expensive"],"normalization":"translation"},{"id":"3","prompt":"Как смотрятся эти свитеры?","acceptedAnswers":["How do these sweaters look?","How do these sweaters look"],"normalization":"translation"},{"id":"4","prompt":"Они выглядят новыми.","acceptedAnswers":["They look new.","They look new"],"normalization":"translation"},{"id":"5","prompt":"Как выглядит та блузка?","acceptedAnswers":["What does that blouse look like?","How does that blouse look?","What does that blouse look like","How does that blouse look"],"normalization":"translation"},{"id":"6","prompt":"Она похожа на платье.","acceptedAnswers":["It looks like a dress.","It looks like a dress"],"normalization":"translation"}]}},{"role":"translation","exercise":{"version":1,"id":"L1-homework-2","kind":"writing","title":"Translate into English.","instruction":"Переведите на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Как смотрится та юбка?","acceptedAnswers":["How does that skirt look?","How does that skirt look"],"normalization":"translation"},{"id":"2","prompt":"Она выглядит дешёвой.","acceptedAnswers":["It looks cheap.","It looks cheap"],"normalization":"translation"},{"id":"3","prompt":"Как смотрятся те костюмы?","acceptedAnswers":["How do those suits look?","How do those suits look"],"normalization":"translation"},{"id":"4","prompt":"Они выглядят старыми.","acceptedAnswers":["They look old.","They look old"],"normalization":"translation"},{"id":"5","prompt":"Как смотрится эта шляпа?","acceptedAnswers":["How does this hat look?","How does this hat look"],"normalization":"translation"},{"id":"6","prompt":"Ты отлично выглядишь в этой шляпе!","acceptedAnswers":["You look great in this hat!","You look good in this hat!","You look great in this hat","You look good in this hat"],"normalization":"translation"}]}}],"reference":{"version":1,"id":"a12w4l1-language-focus-homework-rule","kind":"rule-page","title":"Как описать внешний вид вещи","blocks":[{"type":"rule","title":"Как описать внешний вид вещи","text":"Когда вы хотите сказать, как выглядит вещь, используйте look / looks + прилагательное. Например, The sweater looks warm — «Свитер выглядит тёплым». Вы делитесь впечатлением по внешнему виду.\n\nЕсли вещь напоминает вам другую, используйте look / looks like + существительное или сочетание с ним: This coat looks like my old coat — «Это пальто похоже на моё старое пальто». Здесь like означает сходство, а не «нравится».\n\nСравните:\nIt looks good. — Мы описываем впечатление.\nIt looks like my coat. — Мы говорим, на что вещь похожа.\n\nФорма глагола зависит от того, о ком или о чём вы говорите:\nI / you / we / they → look\nhe / she / it → looks\n\nПоэтому об одном предмете говорим The coat looks good, а о нескольких — The coats look good.\n\nПосле like действуют знакомые правила артиклей: like a coat, like an old coat, но like my coat — перед my артикль не нужен.\n\nЧтобы спросить о внешнем впечатлении, используйте How does it look? — «Как это выглядит?» После does глагол look стоит без окончания -s.","highlights":["look / looks + прилагательное","The sweater looks warm","look / looks like + существительное или сочетание с ним","This coat looks like my old coat","like","It looks good.","It looks like my coat.","I / you / we / they → look","he / she / it → looks","The coat looks good","The coats look good","like a coat","like an old coat","like my coat","my","How does it look?","does","look","-s"]}]},"exercises":[{"version":1,"id":"a12w4l1-words","kind":"matching","title":"Match the pictures with the words.","layout":"picture-word","items":[{"id":"picture-coat","text":"Picture 1","assetId":"A1M4L1_IMAGE_01","alt":"A coat","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/coat-cutout.webp","imageWidth":1122,"imageHeight":1402,"correctId":"coat"},{"id":"picture-sweater","text":"Picture 2","assetId":"A1M4L1_IMAGE_02","alt":"A sweater","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/sweater-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"sweater"},{"id":"picture-blouse","text":"Picture 3","assetId":"A1M4L1_IMAGE_03","alt":"A blouse","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/blouse-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"blouse"},{"id":"picture-skirt","text":"Picture 4","assetId":"A1M4L1_IMAGE_04","alt":"A skirt","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/skirt-cutout.webp","imageWidth":1122,"imageHeight":1402,"correctId":"skirt"},{"id":"picture-suit","text":"Picture 5","assetId":"A1M4L1_IMAGE_05","alt":"A suit","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/suit-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"suit"},{"id":"picture-hat","text":"Picture 6","assetId":"A1M4L1_IMAGE_06","alt":"A hat","image":"assets/lesson-media/a1-2/module-4/lesson-1/images/hat-cutout.webp","imageWidth":1254,"imageHeight":1254,"correctId":"hat"}],"options":[{"id":"skirt","text":"skirt"},{"id":"hat","text":"hat"},{"id":"coat","text":"coat"},{"id":"suit","text":"suit"},{"id":"blouse","text":"blouse"},{"id":"sweater","text":"sweater"}]},{"version":1,"id":"a12w4l1-language-practice","kind":"gaps","title":"Choose the correct option.","inputMode":"select","items":[{"id":"sentence4","segments":["This blouse ",{"id":"look4","answers":["looks like"],"options":["looks like","looks"]}," my old blouse."]},{"id":"sentence2","segments":["These sweaters ",{"id":"look2","answers":["look like"],"options":["look","look like"]}," my sweaters at home."]},{"id":"sentence5","segments":["How does this suit ",{"id":"look5","answers":["look"],"options":["looks","look"]},"?"]},{"id":"sentence1","segments":["This coat ",{"id":"look1","answers":["looks"],"options":["looks","looks like"]}," expensive."]},{"id":"sentence3","segments":["This hat ",{"id":"look3","answers":["looks"],"options":["looks","look"]}," unusual."]}]},{"version":1,"id":"L1-homework-1","kind":"writing","title":"Translate into English.","instruction":"Переведите на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Как смотрится это пальто?","acceptedAnswers":["How does this coat look?","How does this coat look"],"normalization":"translation"},{"id":"2","prompt":"Оно выглядит дорогим.","acceptedAnswers":["It looks expensive.","It looks expensive"],"normalization":"translation"},{"id":"3","prompt":"Как смотрятся эти свитеры?","acceptedAnswers":["How do these sweaters look?","How do these sweaters look"],"normalization":"translation"},{"id":"4","prompt":"Они выглядят новыми.","acceptedAnswers":["They look new.","They look new"],"normalization":"translation"},{"id":"5","prompt":"Как выглядит та блузка?","acceptedAnswers":["What does that blouse look like?","How does that blouse look?","What does that blouse look like","How does that blouse look"],"normalization":"translation"},{"id":"6","prompt":"Она похожа на платье.","acceptedAnswers":["It looks like a dress.","It looks like a dress"],"normalization":"translation"}]},{"version":1,"id":"L1-homework-2","kind":"writing","title":"Translate into English.","instruction":"Переведите на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Как смотрится та юбка?","acceptedAnswers":["How does that skirt look?","How does that skirt look"],"normalization":"translation"},{"id":"2","prompt":"Она выглядит дешёвой.","acceptedAnswers":["It looks cheap.","It looks cheap"],"normalization":"translation"},{"id":"3","prompt":"Как смотрятся те костюмы?","acceptedAnswers":["How do those suits look?","How do those suits look"],"normalization":"translation"},{"id":"4","prompt":"Они выглядят старыми.","acceptedAnswers":["They look old.","They look old"],"normalization":"translation"},{"id":"5","prompt":"Как смотрится эта шляпа?","acceptedAnswers":["How does this hat look?","How does this hat look"],"normalization":"translation"},{"id":"6","prompt":"Ты отлично выглядишь в этой шляпе!","acceptedAnswers":["You look great in this hat!","You look good in this hat!","You look great in this hat","You look good in this hat"],"normalization":"translation"}]}]}'::jsonb) on conflict(lesson_id) do update set definition=excluded.definition;
insert into homework_private.templates(lesson_id,definition) values ('a1-2-w4-l2','{"id":"a1-2-w4-l2","version":"20261004-flow-3","level":"A1.2","title":"Оценка","steps":[{"role":"words","exercise":{"version":1,"id":"a12w4l2-picture-word","kind":"matching","layout":"picture-word","title":"Match the pictures with the words.","instruction":"Click the box and choose the correct word.","items":[{"id":"pw1","text":"coat","image":"Clothes.png","alt":"A brown coat","crop":{"x":34,"y":58.3,"w":10.8,"h":21.5},"correctId":"coat"},{"id":"pw2","text":"sweater","image":"Clothes.png","alt":"A cream sweater","crop":{"x":45,"y":58.4,"w":11.2,"h":17.2},"correctId":"sweater"},{"id":"pw3","text":"blouse","image":"Clothes.png","alt":"A blue blouse","crop":{"x":56.5,"y":58.3,"w":11,"h":18.2},"correctId":"blouse"},{"id":"pw4","text":"skirt","image":"Clothes.png","alt":"A pink skirt","crop":{"x":33.8,"y":79,"w":12,"h":15.2},"correctId":"skirt"},{"id":"pw5","text":"suit","image":"Clothes.png","alt":"A dark blue suit","crop":{"x":45.5,"y":74.7,"w":10.5,"h":23},"correctId":"suit"},{"id":"pw6","text":"hat","image":"Clothes.png","alt":"A straw hat with a black bow","crop":{"x":56.5,"y":78.8,"w":12.5,"h":14},"correctId":"hat"}],"options":[{"id":"suit","text":"suit"},{"id":"coat","text":"coat"},{"id":"hat","text":"hat"},{"id":"blouse","text":"blouse"},{"id":"sweater","text":"sweater"},{"id":"skirt","text":"skirt"}]}},{"role":"listenRepeat","exercise":{"version":1,"id":"a12w4l2-listen-repeat","kind":"audio","layout":"listen-repeat","title":"Listen and repeat.","instruction":"","items":[{"id":"lr1","text":"coat","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l2/coat.mp3","example":"This is a coat.","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l2/this-is-a-coat.mp3"},{"id":"lr2","text":"sweater","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l2/