insert into homework_private.templates(lesson_id,definition) values ('a1-2-w4-l3','{"id":"a1-2-w4-l3","version":"20261004-flow-3","level":"A1.2","title":"Выбор","steps":[{"role":"words","exercise":{"version":1,"id":"L3-M02","kind":"matching","title":"Match the pictures with the words.","layout":"picture-word","items":[{"id":"L3_IMG_01","mediaRef":"L3_IMG_01","text":"Picture 1","correctId":"scarf","assetId":"L3_IMG_01","alt":"Picture 1","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/scarf-cutout.webp","imageWidth":482,"imageHeight":486},{"id":"L3_IMG_02","mediaRef":"L3_IMG_02","text":"Picture 2","correctId":"belt","assetId":"L3_IMG_02","alt":"Picture 2","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/belt-cutout.webp","imageWidth":494,"imageHeight":275},{"id":"L3_IMG_03","mediaRef":"L3_IMG_03","text":"Picture 3","correctId":"gloves","assetId":"L3_IMG_03","alt":"Picture 3","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/gloves-cutout.webp","imageWidth":416,"imageHeight":480},{"id":"L3_IMG_04","mediaRef":"L3_IMG_04","text":"Picture 4","correctId":"cap","assetId":"L3_IMG_04","alt":"Picture 4","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/cap-cutout.webp","imageWidth":501,"imageHeight":371},{"id":"L3_IMG_05","mediaRef":"L3_IMG_05","text":"Picture 5","correctId":"tie","assetId":"L3_IMG_05","alt":"Picture 5","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/tie-cutout.webp","imageWidth":311,"imageHeight":488},{"id":"L3_IMG_06","mediaRef":"L3_IMG_06","text":"Picture 6","correctId":"sunglasses","assetId":"L3_IMG_06","alt":"Picture 6","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/sunglasses-cutout.webp","imageWidth":522,"imageHeight":249}],"options":[{"id":"sunglasses","text":"sunglasses"},{"id":"tie","text":"tie"},{"id":"scarf","text":"scarf"},{"id":"cap","text":"cap"},{"id":"gloves","text":"gloves"},{"id":"belt","text":"belt"}]}},{"role":"listenRepeat","exercise":{"version":1,"id":"L3-M03","kind":"audio","title":"Listen and repeat.","layout":"listen-repeat","audioPending":true,"items":[{"id":"L3_W01","text":"scarf","mediaRef":"L3_W01","example":"My scarf is on the chair.","exampleMediaRef":"L3_E01","audioId":"L3_W01","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_W01.mp3","exampleAudioId":"L3_E01","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_E01.mp3"},{"id":"L3_W02","text":"belt","mediaRef":"L3_W02","example":"Do you have a belt for these pants?","exampleMediaRef":"L3_E02","audioId":"L3_W02","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_W02.mp3","exampleAudioId":"L3_E02","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_E02.mp3"},{"id":"L3_W03","text":"gloves","mediaRef":"L3_W03","example":"I need my gloves. It’s cold.","exampleMediaRef":"L3_E03","audioId":"L3_W03","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_W03.mp3","exampleAudioId":"L3_E03","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_E03.mp3"},{"id":"L3_W04","text":"cap","mediaRef":"L3_W04","example":"Can you put my cap in the backpack, please?","exampleMediaRef":"L3_E04","audioId":"L3_W04","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_W04_r2.mp3?v=20260927-ready","exampleAudioId":"L3_E04","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_E04.mp3"},{"id":"L3_W05","text":"tie","mediaRef":"L3_W05","example":"My brother needs a tie for work.","exampleMediaRef":"L3_E05","audioId":"L3_W05","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_W05_tie-from-sentence-v2.wav?v=20260927-ready","exampleAudioId":"L3_E05","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_E05.mp3"},{"id":"L3_W06","text":"sunglasses","mediaRef":"L3_W06","example":"Where are my sunglasses? I need them today.","exampleMediaRef":"L3_E06","audioId":"L3_W06","audio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_W06.mp3","exampleAudioId":"L3_E06","exampleAudio":"https://xpeywyonbapnvtjnwawi.supabase.co/storage/v1/object/public/course-audio/a1-2/w4/l3/listen-repeat/L3_E06.mp3"}]}},{"role":"practice","exercise":{"version":1,"id":"L3-M07-meanings","kind":"matching","title":"Match the sentences with their meanings.","items":[{"id":"1","text":"I think it looks good.","correctId":"C"},{"id":"2","text":"What do you think?","correctId":"B"},{"id":"3","text":"I like this scarf because it looks warm.","correctId":"A"}],"options":[{"id":"A","text":"Мне нравится этот шарф, потому что он выглядит тёплым."},{"id":"B","text":"Что вы думаете?"},{"id":"C","text":"Мне кажется, это хорошо выглядит."}]}},{"role":"practice","exercise":{"version":1,"id":"L3-M08-question-meaning","kind":"choice","title":"Choose the question for each answer.","items":[{"id":"1","prompt":"“This cap.”","options":[{"id":"A","text":"Which cap do you want?"},{"id":"B","text":"Why do you want this cap?"}],"correctId":"A"},{"id":"2","prompt":"“Because it’s cold.”","options":[{"id":"A","text":"Which scarf do you need?"},{"id":"B","text":"Why do you need a scarf?"}],"correctId":"B"},{"id":"3","prompt":"“I think it looks good.”","options":[{"id":"A","text":"How much is it?"},{"id":"B","text":"What do you think?"}],"correctId":"B"}]}},{"role":"rule","exercise":{"version":1,"id":"L3-M07-rule-homework-rule","kind":"rule-page","title":"Как высказать мнение и объяснить причину","blocks":[{"type":"rule","title":"Как высказать мнение и объяснить причину","text":"Чтобы высказать своё мнение, используйте I think + предложение: I think these gloves look good — «Мне кажется, эти перчатки хорошо выглядят». После I think вы сообщаете свою мысль обычным предложением.\n\nСпросить мнение собеседника можно так: What do you think? — «Что вы думаете?» Например, в ответ можно сказать: I think it looks good.\n\nЕсли нужно объяснить выбор, добавьте because + предложение с причиной: I want this scarf because it’s warm — «Я хочу этот шарф, потому что он тёплый». В разговоре ответ на вопрос о причине может начинаться с because: Because it’s warm.","highlights":["I think + предложение","I think these gloves look good","I think","What do you think?","I think it looks good.","because + предложение с причиной","I want this scarf because it’s warm","because","Because it’s warm."]}]}},{"role":"rule","exercise":{"version":1,"id":"L3-M08-explanation-homework-rule","kind":"rule-page","title":"Как спросить о выборе и причине","blocks":[{"type":"rule","title":"Как спросить о выборе и причине","text":"Когда перед вами несколько вариантов, which помогает спросить, какой из них выбирает человек: Which cap do you like? Если уже понятно, о какой вещи речь, можно сказать Which one do you like? Здесь one заменяет название одного предмета; после one повторять cap не нужно.\n\nО причине спрашиваем с why: Why do you like it? — «Почему вам это нравится?» Ответ объясняет причину: Because it looks good.\n\nПорядок вопроса знаком по Present Simple: Which/Why + do/does + подлежащее + глагол. Название предмета после which относится к вопросительной части: Which cap do you want? С he/she/it используем does, а основной глагол остаётся без -s: Why does she like it?\n\nЕсли говорим о нескольких предметах, называем их прямо: Which gloves do you like? В дальнейшем заменяем их на they/them: They look warm. Why do you like them?","highlights":["which","Which cap do you like?","Which one do you like?","one","cap","why","Why do you like it?","Because it looks good.","Which/Why + do/does + подлежащее + глагол","Which cap do you want?","he/she/it","does","-s","Why does she like it?","Which gloves do you like?","they/them","They look warm. Why do you like them?"]}]}},{"role":"translation","exercise":{"version":1,"id":"L3-homework-1","kind":"writing","title":"Translate into English.","instruction":"Переведите на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Какой тебе нравится: этот шарф или тот?","acceptedAnswers":["Which one do you like: this scarf or that one?","Which do you like: this scarf or that one?","Which scarf do you like: this one or that one?","Which one do you like: this scarf or that one","Which one do you like this scarf or that one","Which do you like: this scarf or that one","Which do you like this scarf or that one","Which scarf do you like: this one or that one","Which scarf do you like this one or that one"],"normalization":"translation"},{"id":"2","prompt":"Мне нравится тот, потому что он красивый.","acceptedAnswers":["I like that one because it is beautiful.","I like that one because it is pretty.","I like that one because it''s beautiful.","I like that one because it''s pretty.","I like that one because it is beautiful","I like that one because it is pretty","I like that one because it’s beautiful.","I like that one because it''s beautiful","I like that one because it’s pretty.","I like that one because it''s pretty"],"normalization":"translation"},{"id":"3","prompt":"Какие тебе нравятся: эти перчатки или те?","acceptedAnswers":["Which ones do you like: these gloves or those?","Which ones do you like: these gloves or those ones?","Which gloves do you like: these or those?","Which ones do you like: these gloves or those","Which ones do you like these gloves or those","Which ones do you like: these gloves or those ones","Which ones do you like these gloves or those ones","Which gloves do you like: these or those","Which gloves do you like these or those"],"normalization":"translation"},{"id":"4","prompt":"Мне нравятся эти, потому что они яркие.","acceptedAnswers":["I like these because they are bright.","I like these ones because they are bright.","I like these because they''re bright.","I like these ones because they''re bright.","I like these because they are bright","I like these ones because they are bright","I like these because they’re bright.","I like these because they''re bright","I like these ones because they’re bright.","I like these ones because they''re bright"],"normalization":"translation"},{"id":"5","prompt":"Что ты думаешь?","acceptedAnswers":["What do you think?","What do you think"],"normalization":"translation"},{"id":"6","prompt":"Я думаю, этот ремень слишком тёмный.","acceptedAnswers":["I think this belt is too dark.","I think this belt is too dark"],"normalization":"translation"}]}},{"role":"translation","exercise":{"version":1,"id":"L3-homework-2","kind":"writing","title":"Translate into English.","instruction":"Переведите на английский.","responseMode":"accepted","revealPossibleAnswers":false,"items":[{"id":"1","prompt":"Какие тебе нравятся: эти солнцезащитные очки или те?","acceptedAnswers":["Which ones do you like: these sunglasses or those?","Which ones do you like: these sunglasses or those ones?","Which sunglasses do you like: these or those?","Which ones do you like: these sunglasses or those","Which ones do you like these sunglasses or those","Which ones do you like: these sunglasses or those ones","Which ones do you like these sunglasses or those ones","Which sunglasses do you like: these or those","Which sunglasses do you like these or those"],"normalization":"translation"},{"id":"2","prompt":"Мне нравятся те, потому что они простые.","acceptedAnswers":["I like those because they are plain.","I like those ones because they are plain.","I like those because they are simple.","I like those ones because they are simple.","I like those because they''re plain.","I like those ones because they''re plain.","I like those because they''re simple.","I like those ones because they''re simple.","I like those because they are plain","I like those ones because they are plain","I like those because they are simple","I like those ones because they are simple","I like those because they’re plain.","I like those because they''re plain","I like those ones because they’re plain.","I like those ones because they''re plain","I like those because they’re simple.","I like those because they''re simple","I like those ones because they’re simple.","I like those ones because they''re simple"],"normalization":"translation"},{"id":"3","prompt":"Почему тебе нравится эта кепка?","acceptedAnswers":["Why do you like this cap?","Why do you like this cap"],"normalization":"translation"},{"id":"4","prompt":"Потому что она дешёвая.","acceptedAnswers":["Because it is cheap.","Because it''s cheap.","Because it is cheap","Because it’s cheap.","Because it''s cheap"],"normalization":"translation"},{"id":"5","prompt":"Что ты думаешь?","acceptedAnswers":["What do you think?","What do you think"],"normalization":"translation"},{"id":"6","prompt":"Я думаю, тот галстук слишком красочный.","acceptedAnswers":["I think that tie is too colorful.","I think that tie is too colourful.","I think that tie is too colorful","I think that tie is too colourful"],"normalization":"translation"}]}}],"reference":{"version":1,"id":"L3-M07-rule-homework-rule","kind":"rule-page","title":"Как высказать мнение и объяснить причину","blocks":[{"type":"rule","title":"Как высказать мнение и объяснить причину","text":"Чтобы высказать своё мнение, используйте I think + предложение: I think these gloves look good — «Мне кажется, эти перчатки хорошо выглядят». После I think вы сообщаете свою мысль обычным предложением.\n\nСпросить мнение собеседника можно так: What do you think? — «Что вы думаете?» Например, в ответ можно сказать: I think it looks good.\n\nЕсли нужно объяснить выбор, добавьте because + предложение с причиной: I want this scarf because it’s warm — «Я хочу этот шарф, потому что он тёплый». В разговоре ответ на вопрос о причине может начинаться с because: Because it’s warm.","highlights":["I think + предложение","I think these gloves look good","I think","What do you think?","I think it looks good.","because + предложение с причиной","I want this scarf because it’s warm","because","Because it’s warm."]}]},"exercises":[{"version":1,"id":"L3-M02","kind":"matching","title":"Match the pictures with the words.","layout":"picture-word","items":[{"id":"L3_IMG_01","mediaRef":"L3_IMG_01","text":"Picture 1","correctId":"scarf","assetId":"L3_IMG_01","alt":"Picture 1","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/scarf-cutout.webp","imageWidth":482,"imageHeight":486},{"id":"L3_IMG_02","mediaRef":"L3_IMG_02","text":"Picture 2","correctId":"belt","assetId":"L3_IMG_02","alt":"Picture 2","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/belt-cutout.webp","imageWidth":494,"imageHeight":275},{"id":"L3_IMG_03","mediaRef":"L3_IMG_03","text":"Picture 3","correctId":"gloves","assetId":"L3_IMG_03","alt":"Picture 3","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/gloves-cutout.webp","imageWidth":416,"imageHeight":480},{"id":"L3_IMG_04","mediaRef":"L3_IMG_04","text":"Picture 4","correctId":"cap","assetId":"L3_IMG_04","alt":"Picture 4","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/cap-cutout.webp","imageWidth":501,"imageHeight":371},{"id":"L3_IMG_05","mediaRef":"L3_IMG_05","text":"Picture 5","correctId":"tie","assetId":"L3_IMG_05","alt":"Picture 5","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/tie-cutout.webp","imageWidth":311,"imageHeight":488},{"id":"L3_IMG_06","mediaRef":"L3_IMG_06","text":"Picture 6","correctId":"sunglasses","assetId":"L3_IMG_06","alt":"Picture 6","image":"assets/lesson-media/a1-2/module-4/lesson-3/media/sunglasses-cutout.webp","imageWidth":522,"imageHeight":249}],"options":[{"i